const __aivicBundle_1_evaluateDemandForecastImprovement = (() => {
  function evaluateDemandForecastImprovement(
    input: DemandForecastEvaluationInput
  ): DemandForecastEvaluationResult {
    const { forecast_value, actual_value, threshold_percentage } = input;
  
    // 乖離率を計算: |予測値 - 実績値| / 予測値 * 100
    const divergence_percentage =
      Math.abs((forecast_value - actual_value) / forecast_value) * 100;
  
    // 乖離率が閾値以下なら改善不要、超過なら改善要と判定
    const improvement_required = divergence_percentage > threshold_percentage;
  
    // 判定結果に基づいてステータスと表示文を決定
    const improvement_status = improvement_required ? "改善要" : "改善不要";
    const decision_display = improvement_required ? "改善実施" : "改善見送り";
  
    // ログ記録フラグ（業務上、判定結果は常に記録される）
    const log_recorded = true;
  
    return {
      divergence_percentage,
      improvement_required,
      improvement_status,
      decision_display,
      log_recorded,
    };
  }
  return { evaluateDemandForecastImprovement };
})();
