const __aivicBundle_7_identifyRejectionTargets = (() => {
  function identifyRejectionTargets(input: {
    purchase_trend_id: string;
    trend_data: any;
    rejection_reason: string;
  }): RejectionTargetsIdentificationResult {
    const { purchase_trend_id, trend_data, rejection_reason } = input;
  
    const target_fields: RejectionTargetField[] = [];
  
    // 却下理由から対象フィールドを抽出
    if (
      rejection_reason.includes('冬季') &&
      trend_data.seasonal_pattern?.winter !== undefined
    ) {
      target_fields.push({
        field_name: 'seasonal_pattern.winter',
        current_value: trend_data.seasonal_pattern.winter,
        flag_reason: '却下理由に明示: 冬季係数が過度',
        priority: 'high',
      });
    }
  
    // 異常値フラグを検出
    if (
      trend_data.anomaly_flags &&
      Array.isArray(trend_data.anomaly_flags) &&
      trend_data.anomaly_flags.length > 0
    ) {
      const anomaly_categories = trend_data.anomaly_flags
        .map((flag: any) => flag.category)
        .join(', ');
      target_fields.push({
        field_name: 'anomaly_flags',
        current_count: trend_data.anomaly_flags.length,
        flag_reason: `異常値が複数検出: ${anomaly_categories}`,
        priority: 'high',
      });
    }
  
    // データ期間を対象に追加
    if (trend_data.data_period_start && trend_data.data_period_end) {
      target_fields.push({
        field_name: 'data_period',
        flag_reason: '異常値が集中した期間を再検証要',
        priority: 'medium',
      });
    }
  
    return {
      purchase_trend_id,
      target_fields,
      identified_at: new Date(),
    };
  }
  return { identifyRejectionTargets };
})();
