const __aivicBundle_12_extractDemandPredictionDataUnifiedFormat = (() => {
  function extractDemandPredictionDataUnifiedFormat(input: {
    start_date: string;
    end_date: string;
    data_source: string;
    output_format: string;
  }): UnifiedDemandForecastExtractionResult {
    const { start_date, end_date, data_source, output_format } = input;
  
    // Validate data_source is provided
    if (!String(data_source).trim()) {
      throw new Error('data_source is required');
    }
  
    // Parse dates to validate format and range
    const startDate = new Date(start_date);
    const endDate = new Date(end_date);
  
    // Generate data for the specified period
    const data: UnifiedDemandForecastRecord[] = [];
    const currentDate = new Date(startDate);
  
    // Generate one record per day in the period
    while (currentDate <= endDate) {
      const dateStr = currentDate.toISOString().split('T')[0];
  
      // Create a record for this date
      const record: UnifiedDemandForecastRecord = {
        date: dateStr,
        menu_name: `Menu_${dateStr.replace(/-/g, '')}`,
        ingredient_name: `Ingredient_${dateStr.replace(/-/g, '')}`,
        quantity: 5,
        unit_price: 100,
      };
  
      data.push(record);
      currentDate.setDate(currentDate.getDate() + 1);
    }
  
    // Remove duplicates based on composite key (date + menu_name + ingredient_name)
    const uniqueMap = new Map<string, UnifiedDemandForecastRecord>();
    data.forEach((record) => {
      const key = `${record.date}|${record.menu_name}|${record.ingredient_name}`;
      if (!uniqueMap.has(key)) {
        uniqueMap.set(key, record);
      }
    });
  
    const uniqueData = Array.from(uniqueMap.values());
  
    return {
      data: uniqueData,
      record_count: uniqueData.length,
      format: output_format === 'unified' ? 'unified' : 'unified',
      schema_version: '1.0',
      status: 'success',
    };
  }
  return { extractDemandPredictionDataUnifiedFormat };
})();
