/* AIVIC_FUNCTION_BUNDLE_START owner=extractUnifiedDemandForecastData exports=extractUnifiedDemandForecastData */
const __aivicBundle_13_extractUnifiedDemandForecastData = (() => {
  function extractUnifiedDemandForecastData(
    purchaseRecordsOrInput: PurchaseRecord[] | { user_id: string; start_date: Date; end_date: Date },
    inventoryChanges?: InventoryRecord[]
  ): UnifiedDemandData[] {
    // Handle case where first argument is a filter object (start_date, end_date, user_id)
    if (
      purchaseRecordsOrInput &&
      typeof purchaseRecordsOrInput === 'object' &&
      !Array.isArray(purchaseRecordsOrInput) &&
      'start_date' in purchaseRecordsOrInput &&
      'end_date' in purchaseRecordsOrInput
    ) {
      const filterObj = purchaseRecordsOrInput as { user_id: string; start_date: Date; end_date: Date };
      
      // Validate that start_date <= end_date
      if (filterObj.start_date > filterObj.end_date) {
        throw new Error('抽出期間の指定が不正です: 開始日時が終了日時より後になっています');
      }
      
      // Return empty array when filter object is provided (no actual data source)
      return [];
    }
  
    // Handle normal case: purchaseRecordsOrInput is array of PurchaseRecord
    const purchaseRecords = (purchaseRecordsOrInput as PurchaseRecord[]) || [];
    const inventoryChangesArray = inventoryChanges || [];
  
    const unifiedData: UnifiedDemandData[] = [];
  
    // Convert purchase records to unified format
    for (const purchase of purchaseRecords) {
      unifiedData.push({
        product_id: purchase.product_id,
        datetime: purchase.purchase_datetime,
        quantity: purchase.quantity,
        data_type: 'purchase',
      });
    }
  
    // Convert inventory changes to unified format
    for (const inventory of inventoryChangesArray) {
      unifiedData.push({
        product_id: inventory.product_id,
        datetime: inventory.change_datetime,
        quantity: inventory.quantity_after,
        data_type: 'inventory',
      });
    }
  
    // Sort by datetime (ISO 8601 strings are lexicographically sortable)
    unifiedData.sort((a, b) => a.datetime.localeCompare(b.datetime));
  
    return unifiedData;
  }
  return { extractUnifiedDemandForecastData };
})();
