        status: 'failure',
        extracted_variables: [],
        error_log: {
          error_message: 'データ不足: 相関分析に必要なサンプル数に達していません',
          actual_sample_count: actualSampleCount,
          required_sample_count: requiredSampleCount,
          shortage_count: shortageCount,
        },
        model_proceed_allowed: false,
        user_notification_required: true,
