    let sumXY = 0;
    let sumX2 = 0;
    let sumY2 = 0;
  
    for (let i = 0; i < n; i++) {
      const dx = x[i] - meanX;
      const dy = y[i] - meanY;
      sumXY += dx * dy;
      sumX2 += dx * dx;
      sumY2 += dy * dy;
    }
  
    const denominator = Math.sqrt(sumX2 * sumY2);
    if (denominator === 0) {
      return { correlation: 0, pValue: 1.0 };
    }
  
    const correlation = sumXY / denominator;
    const tStatistic =
      (correlation * Math.sqrt(n - 2)) / Math.sqrt(1 - correlation * correlation);
